#!/usr/bin/env python3
"""Write the Gazebo world for the shelf scene from config/shelf.yaml.

Usage: make_world.py <shelf.yaml> <out.sdf>

The output is deterministic (no timestamps), so a test can regenerate it and diff it against the
committed world file.
"""

import sys

import yaml

HEADER = """<?xml version="1.0"?>
<!-- GENERATED by pcp_scenes/scripts/make_world.py from pcp_scenes/config/shelf.yaml.
     Do not edit by hand; edit the YAML and regenerate. -->
<sdf version="1.9">
  <world name="shelf">
    <physics name="1ms" type="ignored">
      <max_step_size>0.001</max_step_size>
      <real_time_factor>1.0</real_time_factor>
    </physics>
    <plugin filename="gz-sim-physics-system" name="gz::sim::systems::Physics"/>
    <plugin filename="gz-sim-user-commands-system" name="gz::sim::systems::UserCommands"/>
    <plugin filename="gz-sim-scene-broadcaster-system" name="gz::sim::systems::SceneBroadcaster"/>
    <plugin filename="gz-sim-sensors-system" name="gz::sim::systems::Sensors">
      <render_engine>ogre2</render_engine>
    </plugin>
    <scene>
      <ambient>0.6 0.6 0.6 1</ambient>
      <background>0.85 0.88 0.92 1</background>
      <shadows>false</shadows>
    </scene>
    <light type="directional" name="sun">
      <cast_shadows>false</cast_shadows>
      <pose>0 0 10 0 0 0</pose>
      <diffuse>0.9 0.9 0.9 1</diffuse>
      <specular>0.2 0.2 0.2 1</specular>
      <direction>-0.4 0.3 -0.9</direction>
    </light>
    <model name="ground_plane">
      <static>true</static>
      <link name="link">
        <collision name="collision">
          <geometry><plane><normal>0 0 1</normal><size>10 10</size></plane></geometry>
        </collision>
        <visual name="visual">
          <geometry><plane><normal>0 0 1</normal><size>10 10</size></plane></geometry>
          <material><ambient>0.7 0.7 0.7 1</ambient><diffuse>0.7 0.7 0.7 1</diffuse></material>
        </visual>
      </link>
    </model>
"""

BOX = """        <collision name="{name}_collision">
          <pose>{px} {py} {pz} 0 0 0</pose>
          <geometry><box><size>{sx} {sy} {sz}</size></box></geometry>
        </collision>
        <visual name="{name}_visual">
          <pose>{px} {py} {pz} 0 0 0</pose>
          <geometry><box><size>{sx} {sy} {sz}</size></box></geometry>
          <material>
            <ambient>0.55 0.38 0.22 1</ambient>
            <diffuse>0.55 0.38 0.22 1</diffuse>
          </material>
        </visual>
"""


def make_world(scene: dict) -> str:
    parts = [HEADER, '    <model name="shelf">\n      <static>true</static>\n']
    parts.append('      <link name="link">\n')
    for box in scene["boxes"]:
        (sx, sy, sz), (px, py, pz) = box["size"], box["position"]
        parts.append(BOX.format(name=box["name"], sx=sx, sy=sy, sz=sz, px=px, py=py, pz=pz))
    parts.append("      </link>\n    </model>\n  </world>\n</sdf>\n")
    return "".join(parts)


def main() -> int:
    if len(sys.argv) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    with open(sys.argv[1]) as f:
        scene = yaml.safe_load(f)
    with open(sys.argv[2], "w") as f:
        f.write(make_world(scene))
    return 0


if __name__ == "__main__":
    sys.exit(main())
